module LIFObuffer(
    input [3:0] dataIn,
    input RW,
    input EN,
    input Rst,
    input Clk,
    output EMPTY,
    output FULL,
    output [3:0] dataOut
);
// Parameters
parameter EMPTY_BUFFER = 4'd4;
parameter FULL_BUFFER = 4'd0;
// Internal signals
reg [3:0] stack_mem [0:3];
reg [3:0] SP;
reg [3:0] temp_dataOut;
// Combinational logic
assign EMPTY = (SP == EMPTY_BUFFER);
assign FULL = (SP == FULL_BUFFER);
assign dataOut = temp_dataOut;
// Sequential logic
always @(posedge Clk or posedge Rst) begin
    if(Rst) begin
        SP <= EMPTY_BUFFER;
        for(int i = 0; i < 4; i = i + 1) begin
            stack_mem[i] <= 4'h0;
        end
    end
    else if(EN) begin
        if(!FULL && !RW) begin
            SP <= SP - 1;
            stack_mem[SP] <= dataIn;
        end
        else if(!EMPTY && RW) begin
            SP <= SP + 1;
            temp_dataOut <= stack_mem[SP];
            stack_mem[SP] <= 4'h0;
        end
    end
end
endmodule
